/**
 * One-time runtime-notice relabel (founder decision 2026-10-23: relabel in
 * place). For each row in the founder-approved receipt, replaces only the
 * misapplied leading `David [Claude Code]:` label with the runtime-notice
 * label. The notice text and the reply after it are never changed.
 *
 * Inert until an approved receipt is committed at RECEIPT_PATH (generated by
 * server/scripts/generate-runtime-notice-relabel-receipt.ts and approved by
 * the founder as an exact list). Idempotent, and fail-closed per row:
 *   - current content hashes to preSha256: apply the label span, verify the
 *     result hashes to postSha256, commit;
 *   - current content hashes to postSha256: already applied, skip;
 *   - anything else: the row drifted; leave it untouched and report it.
 * One drifted row never blocks the others or a deploy. Reversal: replace the
 * new label with the old one for the same rows; preSha256 proves the result.
 */
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Pool } from '@neondatabase/serverless';
import type { DataOpResult } from '../run-data-ops';

export const RECEIPT_PATH = join(dirname(fileURLToPath(import.meta.url)), 'relabel-runtime-notices.receipt.json');

const sha256 = (text: string) => createHash('sha256').update(text, 'utf8').digest('hex');

export interface RelabelEntry {
  rowId: string;
  offset: 0;
  oldLabel: string;
  newLabel: string;
  preSha256: string;
  postSha256: string;
}

export type RowOutcome = { status: 'apply'; next: string } | { status: 'already-applied' } | { status: 'drifted' };

/** Decide one row from its current content. Pure; the only way content changes. */
export function relabelContent(content: string, entry: RelabelEntry): RowOutcome {
  const hash = sha256(content);
  if (hash === entry.postSha256) return { status: 'already-applied' };
  if (hash !== entry.preSha256 || entry.offset !== 0 || entry.oldLabel !== 'David [Claude Code]:' ||
      !content.startsWith(`${entry.oldLabel} `)) return { status: 'drifted' };
  const next = entry.newLabel + content.slice(entry.oldLabel.length);
  return sha256(next) === entry.postSha256 ? { status: 'apply', next } : { status: 'drifted' };
}

export async function run(pool: Pool): Promise<DataOpResult> {
  if (!existsSync(RECEIPT_PATH)) return { applied: false, detail: 'no approved receipt committed; nothing to do' };
  const receipt = JSON.parse(readFileSync(RECEIPT_PATH, 'utf8')) as { entries: RelabelEntry[]; listSha256: string };
  if (sha256(JSON.stringify(receipt.entries)) !== receipt.listSha256) throw new Error('receipt list hash does not match its entries');
  let applied = 0;
  let already = 0;
  const drifted: string[] = [];
  for (const entry of receipt.entries) {
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const { rows } = await client.query('SELECT content FROM conversation_memories WHERE id = $1 FOR UPDATE', [entry.rowId]);
      const outcome = rows.length ? relabelContent(rows[0].content, entry) : { status: 'drifted' as const };
      if (outcome.status === 'apply') {
        await client.query('UPDATE conversation_memories SET content = $2 WHERE id = $1', [entry.rowId, outcome.next]);
        applied++;
      } else if (outcome.status === 'already-applied') {
        already++;
      } else {
        drifted.push(entry.rowId);
      }
      await client.query('COMMIT');
    } catch (e) {
      await client.query('ROLLBACK');
      throw e;
    } finally {
      client.release();
    }
  }
  const detail = `relabelled ${applied}, already applied ${already}, drifted and left unchanged ${drifted.length}` +
    (drifted.length ? ` (${drifted.slice(0, 10).join(', ')}${drifted.length > 10 ? ', ...' : ''})` : '');
  return { applied: applied > 0, detail };
}
